import subprocess
import os
import random
import sys

def task_func(directory, file_list):
    if not file_list:
        return None

    chosen = random.choice(file_list)
    path = chosen if os.path.isabs(chosen) else os.path.join(directory, chosen)

    try:
        if path.lower().endswith(".py"):
            proc = subprocess.Popen([sys.executable, path], cwd=directory)
        else:
            try:
                proc = subprocess.Popen([path], cwd=directory)
            except (OSError, ValueError):
                proc = subprocess.Popen(f'"{path}"', cwd=directory, shell=True)

        return proc.poll()
    except Exception:
        return None
